create table RB_LIMIT_ELEMENT_DEF (ELEMENT_ID VARCHAR(50) not null  ,ELEMENT_DESC VARCHAR(50) null  ,ELEMENT_CLASS VARCHAR(50) null  ,ATTR_TYPE VARCHAR(10) null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(ELEMENT_ID));